const load = async ({ fetch }) => {
  const apiUrl = process.env["API_URL"] ?? "http://localhost:3000";
  try {
    const res = await fetch(`${apiUrl}/products`);
    if (!res.ok) return { products: [] };
    const json = await res.json();
    return {
      products: json.data ?? []
    };
  } catch {
    return { products: [] };
  }
};
export {
  load
};
